mod projection_tests {
    use super::*;

    #[test]
    fn render_projection_symbols_result_end_to_end() {
        use crate::types::{SymbolEntry, SymbolKind, SymbolsResult};
        use camino::Utf8PathBuf;
        use std::collections::BTreeMap;

        let mut files = BTreeMap::new();
        files.insert(
            Utf8PathBuf::from("src/lib.rs"),
            vec![SymbolEntry {
                name: "foo".to_string(),
                kind: SymbolKind::Function,
                line: 10,
                // The newline must render as the escape `\n` inside a quoted cell, neither breaking the row nor vanishing.
                signature: Some("fn foo(x)\nsecond line".to_string()),
                // Distinct values in every optional column, so a hardcoded `Value::Null` for any of them shows up.
                owner: Some("MyOwner".to_string()),
                trait_impl: Some("MyTrait".to_string()),
                visibility: Some(crate::types::Visibility::Public),
                kind_detail: Some("static".to_string()),
            }],
        );
        let result = SymbolsResult { files, total_symbol_count: 1, truncation_marker: None, diagnostics: Vec::new() };

        let rendered = render_projection(&result).expect("valid projection must render");
        assert!(
            rendered.starts_with("symbols[1]{file,name,kind,line,signature,owner,traitImpl,visibility,kindDetail}:\n"),
            "got: {rendered}"
        );
        assert!(
            rendered.contains("src/lib.rs,foo,function,10,\"fn foo(x)\\nsecond line\",MyOwner,MyTrait,public,static"),
            "got: {rendered}"
        );
    }

    #[test]
    fn render_projection_search_response_includes_extract_hint() {
        use crate::types::{CodeBlock, RankedBlock, SearchResponse, SymbolKind};
        use camino::Utf8PathBuf;

        let response = SearchResponse {
            results: vec![RankedBlock {
                block: CodeBlock {
                    file: Utf8PathBuf::from("src/lib.rs"),
                    // Line numbers, rank, and score are all distinct so a swapped column is detectable.
                    line_start: 5,
                    line_end: 9,
                    node_kind: SymbolKind::Function,
                    code: "fn foo() {}".to_string(),
                    symbol_signature: Some("fn foo(x)\nsecond line".to_string()),
                    matched_lines: vec![1],
                    matched_keywords: vec!["foo".to_string()],
                },
                bm25_score: 0.75,
                coverage_boost: 0.1,
                node_type_boost: 0.05,
                final_score: 0.92,
                rank: 2,
                parent_context: None,
            }],
            total_blocks_before_truncation: 1,
            truncated: false,
            truncation_marker: None,
            total_bytes: 100,
            total_tokens: 20,
            diagnostics: Vec::new(),
        };

        let rendered = render_projection(&response).expect("valid projection must render");
        assert!(
            rendered.contains("search[1]{file,lineStart,lineEnd,nodeKind,symbolSignature,rank,finalScore}:\n"),
            "got: {rendered}"
        );
        assert!(rendered.contains("src/lib.rs,5,9,function,\"fn foo(x)\\nsecond line\",2,0.92"), "got: {rendered}");
        assert!(!rendered.contains("fn foo() {}"), "code field must never appear in TOON output, got: {rendered}");
        assert!(!rendered.contains("help["), "a non-empty result with no diagnostics has no hints, got: {rendered}");
    }

    #[test]
    fn render_projection_empty_search_response_says_what_went_wrong() {
        use crate::types::SearchResponse;
        use camino::Utf8PathBuf;

        let diagnostic = |kind, path: Option<&str>, message: &str| Diagnostic {
            kind,
            path: path.map(Utf8PathBuf::from),
            message: message.to_owned(),
        };
        let response = SearchResponse {
            results: Vec::new(),
            total_blocks_before_truncation: 0,
            truncated: false,
            truncation_marker: None,
            total_bytes: 0,
            total_tokens: 0,
            diagnostics: vec![
                diagnostic(DiagnosticKind::Skipped, Some("a.ts"), "unreadable"),
                diagnostic(DiagnosticKind::Skipped, Some("b.ts"), "unreadable"),
                diagnostic(DiagnosticKind::Degraded, Some("c.ts"), "parse errors"),
                diagnostic(DiagnosticKind::Skipped, None, "query has no positive terms"),
            ],
        };

        assert_eq!(
            render_projection(&response).expect("must render"),
            "search: []\n\
             help[4]: \"1 file degraded: parse errors: c.ts\",query has no positive terms,\
             \"2 files skipped: unreadable: a.ts, b.ts\",\
             \"only top-level declarations are searched; for text in tests, calls or config try rg\""
        );
    }

    #[test]
    fn diagnostic_lines_name_one_file() {
        let diagnostics = [Diagnostic {
            kind: DiagnosticKind::Degraded,
            path: Some("src/big.ts".into()),
            message: "file too large to parse (300000 bytes, over the cap of 260096)".to_owned(),
        }];
        assert_eq!(
            diagnostic_lines(&diagnostics),
            ["1 file degraded: file too large to parse (300000 bytes, over the cap of 260096): src/big.ts"]
        );
    }

    #[test]
    fn diagnostic_lines_name_three_files_and_count_the_rest() {
        let diagnostics: Vec<Diagnostic> = ["e.ts", "b.ts", "d.ts", "a.ts", "c.ts"]
            .into_iter()
            .map(|path| Diagnostic {
                kind: DiagnosticKind::Skipped,
                path: Some(path.into()),
                message: "unreadable".to_owned(),
            })
            .collect();
        assert_eq!(diagnostic_lines(&diagnostics), ["5 files skipped: unreadable: a.ts, b.ts, c.ts, ...and 2 more"]);
    }

    #[test]
    fn render_projection_budgeted_search_response_reports_the_cut() {
        use crate::budget::{Budget, apply_budget};
        use crate::types::{CodeBlock, RankedBlock, SymbolKind};
